import{_ as t,o as a,c as i,a3 as o}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Style frame panels loaded as iframe (Experimental)","description":"Learn how to enable UIX styling inside supported app and custom-panel frames","frontmatter":{"title":"Style frame panels loaded as iframe (Experimental)","description":"Learn how to enable UIX styling inside supported app and custom-panel frames"},"headers":[],"relativePath":"en/projects/uix/extras/style-frame-panels.md","filePath":"en/projects/uix/extras/style-frame-panels.md","lastUpdated":1792840662000}'),n={name:"en/projects/uix/extras/style-frame-panels.md"};function s(r,e,l,d,p,c){return a(),i("div",null,[...e[0]||(e[0]=[o('<blockquote><p>Adapted from the canonical English UIX documentation by <a href="https://github.com/Lint-Free-Technology/uix" target="_blank" rel="noreferrer">Lint-Free-Technology/uix</a>, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>. Source: <code>dev</code> / <strong>9.0.0-beta.2</strong>, revision <a href="https://github.com/Lint-Free-Technology/uix/commit/26e54e6d4973231a393933e6479ed1b03cc86cd3" target="_blank" rel="noreferrer">26e54e6</a>, reviewed 22 October 2026. This source mirror may describe preview behavior beyond stable 8.4.0. Markup adapted for this site; the <a href="https://uix.lf.technology/" target="_blank" rel="noreferrer">original documentation</a> remains authoritative.</p></blockquote><h1 id="styling-frame-panels-loaded-as-iframe" tabindex="-1">Styling frame panels loaded as iframe <a class="header-anchor" href="#styling-frame-panels-loaded-as-iframe" aria-label="Permalink to &quot;Styling frame panels loaded as iframe&quot;">​</a></h1><p>By default, UIX does not inject styling into frame content. Use this experimental setting to enable the internal UIX runtime in supported same-origin app and custom-panel frames. Host styling with <code>uix-app</code> and <code>uix-panel-custom</code> is unaffected by this option.</p><div class="warning custom-block"><p class="custom-block-title">Framework compatibility</p><p>The frame runtime is thoroughly exercised with Home Assistant&#39;s Lit-based frontend. Iframe apps and custom panels built with other frameworks may have different lifecycle or shadow-DOM behavior. Panels with a conventional light-DOM root and no shadow-root boundaries will generally work well; panels that own and reconcile their DOM reactively, or use complex shadow DOM, need app-specific validation. Inspect the frame, test each selector, and report compatibility issues.</p><p>Non-Lit frames use a stylesheet fallback instead of inserting a <code>uix-node</code> into the app DOM. The fallback supports direct CSS (including templates) but not UIX YAML selector paths; use ordinary CSS selectors in the direct style block.</p></div><h2 id="setting-via-the-integration-ui" tabindex="-1">Setting via the integration UI <a class="header-anchor" href="#setting-via-the-integration-ui" aria-label="Permalink to &quot;Setting via the integration UI&quot;">​</a></h2><p>The option is <strong>unset by default</strong>. To set the option:</p><ol><li>In Home Assistant, go to <strong>Settings → Devices &amp; Services → UI eXtension → Configure</strong>.</li><li>Select <strong>Experimental settings</strong> from the menu.</li><li>Toggle <strong>Style frame panels loaded as iframe</strong> on.</li><li>Save.</li></ol><p>The setting is available immediately across all connected browser sessions. A page reload may be required for the setting to take effect on any currently displayed frame panel.</p><h2 id="behavior-when-set" tabindex="-1">Behavior when set <a class="header-anchor" href="#behavior-when-set" aria-label="Permalink to &quot;Behavior when set&quot;">​</a></h2><p>When this option is set:</p><ul><li>UIX installs its internal, panel-agnostic runtime in supported same-origin app and custom-panel frames.</li><li>custom-panel frames use their panel name as the theme target. App frames try the full add-on slug first and then its repository-independent slug.</li><li>UIX adds a styling node only when the active theme defines a matching frame target. Frames without a matching <code>uix-&lt;target&gt;</code> section are left untouched.</li><li>if UIX detects a theme is not applied, UIX Styling is applied with the currently loaded Home Assistant Frontend theme. Some custom panels like HACS apply the theme, and in this case UIX styling will inherit the applied theme.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>To best way to find the target for <code>uix-&lt;target&gt;</code> is to check your Browser developer console for the UIX loaded info which is generated by <code>uixFrame.js</code>. It will have form similar to:</p><p><span style="background:#CE3226;color:white;padding:2px 5px;font-weight:bold;border-radius:5px;">💡 UIX 8.4.0 IS INSTALLED 💡 for hacs-frontend</span></p><p>The end part of this info is the target e.g. <code>hacs-frontend</code>.</p></div>',12)])])}const f=t(n,[["render",s]]);export{m as __pageData,f as default};
